'use strict';

const async = require('async')
, Emitter = require('events')
, request = require('request')
, webdriver = require('wd');


class WebDriverTestRunner extends Emitter {
  /**
   * Constructor for server wrapper
   * @param {Object} [envProps]
   * @param {Number} [port] Port for localhost resources.
   * @param {Array} [browserSpecs] List of browser specifications
   * @returns {Object} Reference to self.
   */
  constructor (envProps, port, browserSpecs) {
    super();
    this.env = envProps.env;
    this._doQueue(envProps, port, browserSpecs);
    return this;
  }

  /**
   * Queue all browsers in given environment
   * @param {Object} [envProps]
   * @param {Number} [port] Port for localhost resources.
   * @param {Array} [browserSpecs] List of browser specifications
   */
  _doQueue (envProps, port, browserSpecs) {
    const self = this;

    // Queue item handling
    const q = async.queue(function (browserSpec, queueCb) {
      const browser = webdriver.remote(envProps.uri, envProps.port);

      // Start browser, and point to Mocha test runner
      browser.init(browserSpec, function () {
        self.emit('browserStart', browserSpec.description);
        browser.get('http://localhost:' + port + '/test-runner.html',
                    function () {
                      self.emit('browserGet', browserSpec.description);

                      let retries = 5;

                      self._getTestResults.bind(this);
                      self._getTestResults(browser, browserSpec, retries, queueCb);
                    });
      });
    }, envProps.concurrency);

    // Clean up on empty queue
    q.drain = function () {
      self.emit('end');
    };

    // Queue desired browsers through WebDriver
    browserSpecs.forEach(function (browserSpec) {
      q.push(browserSpec, function (err) { // queueCb
        if (err) {
          // Something went wrong with the browser
          self.emit('browserFail', browserSpec.description, err.message);
        }
      });
    });
  }

  /**
   * Get test results from remote.
   * @param {Object} [browser] WebDriver browser instance.
   * @param {Object} [browserSpec] Specs for browser.
   * @param {Number} [retries] Number of retries left.
   * @param {Function} [queueCb] Callback.
   */
  _getTestResults (browser, browserSpec, retries, queueCb) {
    this._resultsHandler.bind(this);
    const self = this;

    browser.safeEval('JSON.stringify(window.mochaResults)',
                    function (err, res) {
                      self._resultsHandler(err, res, browser, browserSpec,
                                           retries, queueCb);
                    });
  }

    /**
   * Get test results from remote.
   * @param {Object} [err]
   * @param {String} [res] Status from browser, as JSON string.
   * @param {Object} [browser] WebDriver browser instance.
   * @param {Object} [browserSpec] Specs for browser.
   * @param {Number} [retries] Number of retries left.
   * @param {Function} [queueCb] Callback.
   */
  _resultsHandler (err, res, browser, browserSpec, retries, queueCb) {
    const self = this;

    if (err) {
      self.emit('browserFail', browserSpec.description, err.message);
      self._setRemoteTestStatus(browser, browserSpec, false);
      queueCb();
      return;
    }

    // Parse results from browser.
    try {
      res = JSON.parse(res);
    } catch (e) {
      res = null;
    }

    if (retries == 0) {
      self.emit('browserMaxRetries', browserSpec.description);
      self._setRemoteTestStatus(browser, browserSpec, false);
      browser.quit();
      queueCb();
    } else if (!res) {
      // No results; try again.
      setTimeout(function () {
        self.emit('wait', browserSpec.description);
        self._getTestResults(browser, browserSpec, retries - 1, queueCb);
      }, 5000);
    } else {
      // Results received.
      if (res.mochaFailed) {
        // Something went wrong with Mocha; perhaps browser is not supported.
        self.emit('mochaFail', browserSpec.description);
      } else {
        self._setRemoteTestStatus(browser, browserSpec, true);
        self.emit('browserDone', browserSpec.description,
                  res.failed, res.passed);
      }
      browser.quit();
      queueCb();
    }
  }

  /**
   * Update remote status for tests run in browser.
   * @param {Object} [browser]
   * @param {Object} [browserSpec]
   * @param {Boolean} [status] true on test pass, false otherwise.
   */
  _setRemoteTestStatus (browser, browserSpec, status) {
    if ('saucelabs' == this.env) {
      const user = browserSpec.username;
      const key = browserSpec.accessKey;

      const props = { passed: status };

      if (process.env.TRAVIS === 'true') {
        props.public = 'public restricted';
        props.build = process.env.TRAVIS_BUILD_NUMBER;
        props.customData = {
          commit: process.env.TRAVIS_COMMIT,
          branch: process.env.TRAVIS_BRANCH
        };
      }

      request({
        method: 'PUT',
        uri: ['https://', user, ':', key, '@saucelabs.com/rest', '/v1/', user,
              '/jobs/', browser.sessionID].join(''),

        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(props)
      });
    }
  }
}


module.exports = WebDriverTestRunner;

